class Solution {
  public int[][] multiply(int[][] mat1, int[][] mat2) {
    int m = mat1.length, k = mat1[0].length, n = mat2[0].length;
    int[][] res = new int[m][n];
    for (int i = 0; i < m; i++)
      for (int t = 0; t < k; t++) {
        if (mat1[i][t] == 0) continue; // skip zeros of the sparse left matrix
        for (int j = 0; j < n; j++) res[i][j] += mat1[i][t] * mat2[t][j];
      }
    return res;
  }
}
